import{_ as t,o,c as a,a2 as r}from"./chunks/framework.Cdp8-jB6.js";const p=JSON.parse('{"title":"UXS-015 — Physics Lab · one card model, three views","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/UXS-015.md","filePath":"uxs/UXS-015.md"}'),i={name:"uxs/UXS-015.md"};function s(n,e,d,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="uxs-015-—-physics-lab-·-one-card-model-three-views" tabindex="-1">UXS-015 — Physics Lab · one card model, three views <a class="header-anchor" href="#uxs-015-—-physics-lab-·-one-card-model-three-views" aria-label="Permalink to &quot;UXS-015 — Physics Lab · one card model, three views&quot;">​</a></h1><blockquote><p>Status · Draft v0.1 Visual fidelity · House-accurate interactive prototypes at kickoff — <code>docs/prototypes/lab/notebook.html</code>, <code>focus.html</code>, <code>canvas.html</code> (real tokens, Bebas Neue / Space Mono / Crimson Pro, the <code>station-blueprint</code> teal grid, KaTeX). They gate Slice 0 per the &quot;visual anchor before UX commit&quot; rule. Numbers and figures in them are <strong>illustrative placeholders, not live kernel output.</strong> IA anchor · §lab — a new top-level surface (<code>/lab</code>); IA.md amendment pending Related PRD · PRD-033 · Related RFC · RFC-037</p></blockquote><h2 id="why-this-uxs-exists" tabindex="-1">Why this UXS exists <a class="header-anchor" href="#why-this-uxs-exists" aria-label="Permalink to &quot;Why this UXS exists&quot;">​</a></h2><p>PRD-033 sets the <em>what/why</em> and RFC-037 the <em>how it&#39;s built</em>; this UXS owns the part that makes or breaks it — <strong>making the Lab feel native to Orrery while introducing a genuinely new interaction (playing with the physics).</strong> The Lab reuses Orrery&#39;s existing design language wholesale; the novelty is the <em>card</em> and the three views over it. Without a pinned model, &quot;play with the formulas&quot; gets designed ad-hoc in scene code. This spec is the contract for the card, the three views, the promote relationship, the honesty line, and the responsive story.</p><h2 id="the-one-idea-three-views-over-one-card-model" tabindex="-1">The one idea: three views over one card model <a class="header-anchor" href="#the-one-idea-three-views-over-one-card-model" aria-label="Permalink to &quot;The one idea: three views over one card model&quot;">​</a></h2><p>The atom is a <strong>card</strong> — a formula instance: <em>(formula id, bound inputs, wiring to other cards, and the <code>FigureSpec</code> it emits)</em>. A card is portable data, so it renders in three views matching three intents:</p><table tabindex="0"><thead><tr><th>View</th><th>Intent</th><th>Shape</th><th>Prototype</th></tr></thead><tbody><tr><td><strong>Notebook</strong> <em>(v1 home)</em></td><td>keeping / building</td><td>ordered, narrated, exportable column of cards</td><td><code>notebook.html</code></td></tr><tr><td><strong>Focus</strong> <em>(v1 detail)</em></td><td>drilling into one card</td><td>full-screen: big figure + full control rail + derivation</td><td><code>focus.html</code></td></tr><tr><td><strong>Canvas</strong> <em>(T2, second workspace)</em></td><td>prototyping</td><td>free spatial graph, output→input wiring on the teal grid</td><td><code>canvas.html</code></td></tr></tbody></table><p>Cards <strong>promote</strong> from Canvas into a Notebook (a card or a wired subgraph). One model, three windows — this is the subsystem, not three routes.</p><h2 id="the-card-the-atom-—-built-entirely-from-existing-parts" tabindex="-1">The card (the atom) — built entirely from existing parts <a class="header-anchor" href="#the-card-the-atom-—-built-entirely-from-existing-parts" aria-label="Permalink to &quot;The card (the atom) — built entirely from existing parts&quot;">​</a></h2><p>Nothing here is a new visual primitive; every part maps to something already shipping. This is <em>why</em> it reads as Orrery:</p><table tabindex="0"><thead><tr><th>Card part</th><th>Reused from</th><th>Tokens</th></tr></thead><tbody><tr><td>Title</td><td>Bebas Neue header</td><td><code>--font-display</code>, letter-spacing 3px</td></tr><tr><td>Equation</td><td>KaTeX (already loaded at <code>/science</code>)</td><td>inline / display mode</td></tr><tr><td>ⓘ symbol deep-links</td><td><code>ScienceChip</code> → <code>/science/[tab]/[section]</code></td><td>teal <code>#4ecdc4</code></td></tr><tr><td>Parameter controls</td><td><code>/plan</code> selector + <code>.readout-grid</code> label/value</td><td>Space Mono 7px label / 11px value</td></tr><tr><td>Drawn figure</td><td><code>station-blueprint.ts</code> teal-grid canvas</td><td>grid <code>rgba(78,205,196,0.09)</code> @ 32px on <code>#04040c</code></td></tr><tr><td>Headline result</td><td><code>.readout-grid</code> strong teal cell + <code>SpacecraftInfoCard</code> live-readout</td><td>teal strong cell 15px</td></tr><tr><td>&quot;Why?&quot; / derivation</td><td><code>WhyPopover</code> (gold) → expand to a <code>Panel</code> in <code>/science</code> reading style</td><td>gold <code>#ffc850</code></td></tr><tr><td>Provenance / honesty line</td><td><code>ImageCredit</code> mono caption</td><td>8px, &quot;computed&quot; vs &quot;illustration&quot;</td></tr></tbody></table><p><strong>Colour discipline is inherited and strict:</strong> teal = figure lines + selection/navigation; <strong>gold = explanation</strong> (Why?, lens story, caveats); mars-red = fail/deficit. Never mixed.</p><h2 id="notebook-v1-home" tabindex="-1">Notebook (v1 home) <a class="header-anchor" href="#notebook-v1-home" aria-label="Permalink to &quot;Notebook (v1 home)&quot;">​</a></h2><p>The surface you land on. A centred worksheet (<code>max-width ~820px</code>) on the teal grid: a Bebas title (&quot;GETTING TO MARS&quot;), then a vertical column of cards. Each card carries its controls, its live figure, its readout, a Why? affordance, and a provenance line. A card may <strong>reference the result of the card above it</strong> (&quot;↳ Δv from above feeds the transfer budget&quot;) — composition without wiring. <code>+ ADD CELL</code> appends. The whole worksheet <strong>exports</strong> (per PRD-033 T1) as a lab-report artifact with placard styling. This is the durable thing; it persists (URL/local/file per RFC-037).</p><h2 id="focus-v1-detail" tabindex="-1">Focus (v1 detail) <a class="header-anchor" href="#focus-v1-detail" aria-label="Permalink to &quot;Focus (v1 detail)&quot;">​</a></h2><p>Drill into a single card — the <code>/plan</code> split, generalized: a big figure stage left on the grid, a persistent control rail right (formula picker, sliders, readout grid, Why?, provenance). Display-mode KaTeX. Invoked from any card in Notebook (and later Canvas). This is where you <em>study</em> one formula; the figure gets room to breathe.</p><h2 id="canvas-t2-—-second-workspace-not-v1" tabindex="-1">Canvas (T2 — second workspace, not v1) <a class="header-anchor" href="#canvas-t2-—-second-workspace-not-v1" aria-label="Permalink to &quot;Canvas (T2 — second workspace, not v1)&quot;">​</a></h2><p>The prototyping whiteboard: cards dragged freely on the grid, each with input/output <strong>sockets</strong>; drag a socket to another card to <strong>wire</strong> output→input, edges drawn in teal. Recompute propagates along edges. <code>+ ADD FORMULA</code> drops a card. When a subgraph is worth keeping, <strong>promote</strong> it into a Notebook. This is the &quot;wire from trajectories down to propulsion&quot; vision — and the expensive part (graph engine, cycle-checking, serialization), which is why it lands after the Notebook proves the card model.</p><h2 id="the-honesty-line-the-make-or-break-made-visual" tabindex="-1">The honesty line (the make-or-break, made visual) <a class="header-anchor" href="#the-honesty-line-the-make-or-break-made-visual" aria-label="Permalink to &quot;The honesty line (the make-or-break, made visual)&quot;">​</a></h2><p>Per PRD-033 §&quot;the honesty line&quot; and PA §&quot;real physics, not approximations that mislead&quot;:</p><ul><li><strong>Computed vs illustrated is always visible.</strong> Every figure carries an <code>ImageCredit</code>-style provenance line: <code>computed · orrery-kernel · &lt;module&gt;</code>. Generative/illustrative art (T3) sits in a distinct register and is labelled <code>illustration</code>, never on the data path.</li><li><strong>Sketchy-but-exact.</strong> The notebook warmth (graph-paper grid, hand-annotated vectors, margin marks) is <strong>deterministic SVG styled to look hand-drawn</strong> — the styling is warm, the content is computed.</li><li><strong>Fail honestly, visibly.</strong> No window / TWR &lt; 1 / insufficient Δv turns the readout <strong>mars-red</strong> and states the reason (the <code>/plan</code> Δv-deficit pattern), never a blank or a hidden failure.</li></ul><h2 id="the-figure-language" tabindex="-1">The figure language <a class="header-anchor" href="#the-figure-language" aria-label="Permalink to &quot;The figure language&quot;">​</a></h2><p>Figures render on the <code>station-blueprint</code> teal hairline grid (near-black <code>#04040c</code>, teal grid, Space Mono axis labels). v1 figure catalogue (all deterministic, from the kernel): transfer ellipse · Δv sensitivity curve · porkchop heatmap · rocket free-body force diagram · ascent profile triptych · EDL entry corridor · orbit/ground-track · sky chart · Tsiolkovsky curve · cislunar ECI. Each is a <code>FigureSpec</code> renderer (RFC-037).</p><h2 id="responsive-mobile" tabindex="-1">Responsive &amp; mobile <a class="header-anchor" href="#responsive-mobile" aria-label="Permalink to &quot;Responsive &amp; mobile&quot;">​</a></h2><ul><li><strong>Notebook is mobile-first</strong> (Orrery&#39;s core principle). The centred column becomes a single full-width stack; cards are full-width; controls stay usable at 44px targets; the nav collapses to the app&#39;s existing mobile pattern. Prototype: <code>notebook.html</code> at 390px reads cleanly.</li><li><strong>Focus</strong> adapts to the <code>Panel</code> bottom-sheet convention on mobile (figure top, controls in the sheet).</li><li><strong>Canvas is desktop-first and has no honest mobile story</strong> — on phones it degrades to a <strong>read-only</strong> rendering of the graph (pan/zoom, tap-to-Focus), never a wiring surface. This is a stated limitation, not a detail.</li></ul><h2 id="accessibility" tabindex="-1">Accessibility <a class="header-anchor" href="#accessibility" aria-label="Permalink to &quot;Accessibility&quot;">​</a></h2><p>Extends the existing patterns (RFC-031): every control is keyboard-reachable and labelled; sliders have number-input equivalents; ⓘ chips and Why? are focusable; figures carry honest <code>aria-label</code>s describing what they compute (never a bare canvas); reduced-motion stills the recompute/redraw transitions; the Notebook is a linear DOM document (keyboard-native by construction); Canvas provides the DOM-mirror list of cards for non-pointer users.</p><h2 id="prototype-coverage-caveats" tabindex="-1">Prototype coverage &amp; caveats <a class="header-anchor" href="#prototype-coverage-caveats" aria-label="Permalink to &quot;Prototype coverage &amp; caveats&quot;">​</a></h2><p>What the kickoff prototypes (<code>docs/prototypes/lab/</code>) <strong>do</strong> establish: the house-accurate chrome, tokens, typefaces, the teal figure grid, the card anatomy, and all three view layouts (Notebook desktop + mobile, Focus, Canvas) — enough to lock the look.</p><p>What they <strong>do not</strong> yet establish (and how each is closed):</p><ul><li><strong>Numbers &amp; figures are illustrative placeholders</strong>, hand-drawn to shape — not live kernel output. Closed when S2 (registry + <code>FigureSpec</code> renderers) lands; the in-build figures replace the mock SVGs.</li><li><strong>Canvas shows layout only</strong> — no live wiring, sockets are static, no recompute. The interactive graph engine is S5; a <strong>promote</strong> interaction mock is gated before that slice.</li><li><strong>No fail-honest / empty / loading frames yet.</strong> The mars-red infeasible state (no window / TWR &lt; 1) gets a mock before <strong>S3</strong>, since it&#39;s core to the honesty line, not an edge case.</li><li><strong>Accessibility isn&#39;t demonstrable in a static shot</strong> — the a11y contract above is spec, verified in-build (keyboard walk, screen-reader labels, reduced-motion) during S3.</li></ul><p>Rule: a state that is load-bearing for trust (fail-honest) or novel (promote/wiring) gets a visual anchor before its slice; ordinary states are proven in-build.</p><h2 id="signature-moments-that-get-a-visual-anchor-before-build" tabindex="-1">Signature moments that get a visual anchor before build <a class="header-anchor" href="#signature-moments-that-get-a-visual-anchor-before-build" aria-label="Permalink to &quot;Signature moments that get a visual anchor before build&quot;">​</a></h2><ol><li><strong>A formula card, live</strong> — slider → figure + readout redraw, Why? open (Notebook).</li><li><strong>Focus on the transfer</strong> — the big ellipse on the grid + control rail (Focus).</li><li><strong>Promote</strong> — pulling a wired subgraph from Canvas into a Notebook (T2, mocked before that slice).</li></ol><p>The first two are covered by the kickoff prototypes; all three are mocked on real screenshots and gated on Marko&#39;s approval before the matching slice ships.</p>',35)])])}const g=t(i,[["render",s]]);export{p as __pageData,g as default};
